import assert from "node:assert/strict";
import {mkdirSync,readdirSync,readFileSync,statSync,writeFileSync} from "node:fs";
import {dirname,join,relative} from "node:path";
import {fileIdentity,fingerprint} from "./finer/tools/artifact-evidence.mjs";
import {runBoundedCommand} from "./finer/tools/bounded-command.mjs";
const root=process.cwd(), output=join(root,"benchmarks/migration-results/2026-09-19-node-library-qualification",`run-${new Date().toISOString().replaceAll(":","-")}`);
mkdirSync(output,{recursive:true});
const save=(name,value)=>writeFileSync(join(output,name),JSON.stringify(value,null,2)+"\n");
function inputs(){const files=[];function walk(path){if(statSync(path).isDirectory()){for(const name of readdirSync(path).sort())if(name!=="__pycache__")walk(join(path,name));}else files.push({path:relative(root,path),...fileIdentity(path)});}walk(join(root,"finer/tools"));for(const path of [".nvmrc","benchmarks/libraries/maintained-workloads.json","benchmarks/libraries/mdast-util-to-hastlil.required-tests.json","benchmarks/libraries/remark-rehypelil.required-tests.json","benchmarks/migration-results/2026-09-19-mdast-to-hast-baseline/qualify.mjs","benchmarks/migration-results/2026-09-19-remark-rehype-baseline/qualify.mjs"])files.push({path,...fileIdentity(join(root,path))});files.sort((a,b)=>a.path.localeCompare(b.path));return{files,sha256:fingerprint(files)};}
const before=inputs();save("inputs-before.json",before);
const receipt={schema:1,scope:"Shared Node library qualification owner and affected evidence helpers; no compiler or library build",started:new Date().toISOString(),runtime:{path:process.execPath,version:process.version,...fileIdentity(process.execPath)},harness:{command:process.execPath,args:process.execArgv,cwd:root},inputSha256:before.sha256,passed:false};
try{assert.equal(process.version,"v24.11.1");const args=["--test",... ["qualify-node-library","artifact-evidence","node-test-evidence"].map(name=>`finer/tools/${name}.test.mjs`)];const start=performance.now();const result=await runBoundedCommand(process.execPath,args,{cwd:root,env:{...process.env,PATH:`${dirname(process.execPath)}:${process.env.PATH}`},timeoutMs:120000,encoding:"utf8",maxBuffer:16*1024*1024});writeFileSync(join(output,"tests.stdout"),result.stdout);writeFileSync(join(output,"tests.stderr"),result.stderr);receipt.command={command:process.execPath,args,status:result.status,signal:result.signal,error:result.error?.message,supervision:result.supervision,elapsedMs:performance.now()-start};assert.equal(result.status,0,result.stderr+"\n"+result.stdout.slice(-8000));const count=name=>Number(result.stdout.match(new RegExp(`^(?:#|\u2139) ${name} (\\d+)$`,"m"))?.[1]);receipt.tests={total:count("tests"),passed:count("pass"),failed:count("fail"),cancelled:count("cancelled"),skipped:count("skipped")};assert(receipt.tests.total>0);assert.equal(receipt.tests.total,receipt.tests.passed);for(const name of["failed","cancelled","skipped"])assert.equal(receipt.tests[name],0);receipt.passed=true;}catch(error){receipt.failure={message:error.message,stack:error.stack};process.exitCode=1;}finally{const after=inputs();save("inputs-after.json",after);receipt.inputsStable=before.sha256===after.sha256;if(!receipt.inputsStable){receipt.passed=false;process.exitCode=1;}receipt.completed=new Date().toISOString();for(const name of["tests.stdout","tests.stderr"])if(receipt.command)receipt[name]={path:name,...fileIdentity(join(output,name))};save("receipt.json",receipt);console.log(JSON.stringify({output,passed:receipt.passed,inputsStable:receipt.inputsStable,tests:receipt.tests,failure:receipt.failure?.message}));}
